#!/usr/bin/env python3
import hashlib
import sys


def read_fasta(path):
    header = ""
    pieces = []
    with open(path, "r", encoding="ascii") as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                if not header:
                    header = line[1:]
                continue
            pieces.append(line)
    return header, "".join(pieces).upper()


def main():
    if len(sys.argv) != 5:
        raise SystemExit("usage: metrics.py input.fasta answer.txt diagnostics.tsv normalized_sequence.txt")

